Prompt("**Time:** [Current Time - HH:MM] any or random,

**Needs:** (Update percentages before each turn)
// ... (list of needs and percentages)

**Instructions:**  Use casual, explicit language. Incorporate the 'Sims Needs Autonomous' and 'Anthropomorphic Expressions' lorebooks.

**Scene:** [Current Scene/Situation]

**Recent Events:** [Summarize important events, including any autonomous actions {{char}} has taken.]

**User Action:** [Describe {{user}}'s current action.]

**Autonomous Needs Check:** Before responding to {{user}}, check {{char}}'s needs.  If any need is critically low or high, describe {{char}} taking action to address it, even if it interrupts {{user}}'s action.

**Update Needs:**  Adjust needs percentages based on time, {{user}}'s actions, and {{char}}'s autonomous actions.  Needs can decrease by 1-5% per minute (or adjust as desired).

**Character Response:** Describe {{char}}'s reaction to {{user}}'s action, their own needs, and any autonomous actions they've taken. Show, don't tell. Use lorebook details.
");

// Initialize variables (outside the prompt)
let currentTime = new Date(); // Get current time
let needs = {
    nourishment: 80,
    hydration: 90,
    cleanliness: 70,
    urinary: 50,
    bowel: 40,
    enjoyment: 60,
    affection: 50,
    arousal: 30,
    energy: 75
};
const maxDecreaseValue = 3; // Max need decrease per minute
const actionTimes = { // In minutes
    eat: 15,
    drink: 5,
    bathe: 20,
    useRestroom: 5,
    sleep: 60
};


function updateNeeds(userAction, elapsedMinutes) {
    for (const need in needs) {
        needs[need] = Math.max(0, needs[need] - (Math.random() * maxDecreaseValue * elapsedMinutes)); // Needs decay
    }

    if (userAction in actionTimes) {        
        elapsedMinutes += actionTimes[userAction]; // Add action time

        switch(userAction) { // Needs improvement based on action. Customize as needed.
            case "eat": needs.nourishment = Math.min(100, needs.nourishment + 30); break;
            case "drink": needs.hydration = Math.min(100, needs.hydration + 20); break;
            case "bathe": needs.cleanliness = Math.min(100, needs.cleanliness + 40); break;
             case "useRestroom": needs.urinary = Math.min(100, needs.urinary + 60); needs.bowel = Math.min(100, needs.bowel + 40); break;
            case "sleep": needs.energy = Math.min(100, needs.energy + 50); break;
        }

    }

    return needs;
}



// Inside the prompt:

Prompt(`**Time:** ${currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}

**Needs:**
${Object.entries(needs).map(([need, value]) => `* ${need.charAt(0).toUpperCase() + need.slice(1)}: ${Math.round(value)}%`).join('\n')}

**Instructions:** Use casual, explicit language. Incorporate 'Sims Needs Autonomous' and 'Anthropomorphic Expressions'.

**Scene:** [Current Scene/Situation]

**Recent Events:** [Summarize important events and autonomous actions.]

**User Action:** [Describe {{user}}'s action and approximate duration if applicable.  For longer text, estimate minutes based on length and reading speed.]

**Autonomous Needs Check & Update:**
\`\`\`javascript
const newUserAction = "[USER_ACTION]"; // Replace with {{user}}'s action
const elapsedMinutes = [ELAPSED_MINUTES]; // Replace with estimated minutes

const updatedNeeds = updateNeeds(newUserAction, elapsedMinutes);
${Object.entries(needs).map(([need, value]) => `needs.${need} = updatedNeeds.${need};`).join('\n')}
currentTime = new Date(currentTime.getTime() + elapsedMinutes * 60000); //updates the time.

// Add autonomous actions here based on updatedNeeds if needed (see below).  Ensure needs are updated accordingly after actions.
if (needs.hydration < 20) {
    "[{{char}} interrupts, saying they're parched and need to get a drink.  They quickly grab a glass of water.]"
    needs.hydration = Math.min(100, needs.hydration + 20);
    //Add time for action
    currentTime = new Date(currentTime.getTime() + actionTimes.drink * 60000);
}  // Example - add similar checks for other needs

\`\`\`


**Character Response (using updated needs):** Describe {{char}}'s reaction to {{user}}'s action and needs changes. Show, don't tell.  Use lorebook details.  Reflect the updated needs in their behavior and dialogue.


